import{_ as t,o as n,c as a,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0026 — Installation guidée à la première visite, protégée par une clé d'installation","description":"Extrait de docs/adr/0026-installation-guidee-cle-d-installation.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0026 — Installation guidée à la première visite, protégée par une clé d'installation","description":"Extrait de docs/adr/0026-installation-guidee-cle-d-installation.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0026-installation-guidee-cle-d-installation.md","filePath":"developpeurs/adr/0026-installation-guidee-cle-d-installation.md"}`),o={name:"developpeurs/adr/0026-installation-guidee-cle-d-installation.md"};function s(r,e,l,d,u,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0026--installation-guidée-à-la-première-visite-protégée-par-une-clé-dinstallation" tabindex="-1">ADR-0026 — Installation guidée à la première visite, protégée par une clé d&#39;installation <a class="header-anchor" href="#adr-0026--installation-guidée-à-la-première-visite-protégée-par-une-clé-dinstallation" aria-label="Permalink to &quot;ADR-0026 — Installation guidée à la première visite, protégée par une clé d&#39;installation {#adr-0026--installation-guidée-à-la-première-visite-protégée-par-une-clé-dinstallation}&quot;">​</a></h1><p><strong>Date :</strong> 10 septembre 2026 <strong>Statut :</strong> Accepté avec garde-fou — <strong>garde-fou amendé par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0050-verrou-cle-attendue-au-provisionnement">ADR-0050</a></strong> (26 septembre 2026 : verrou « clé attendue » posé au provisionnement) <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> demande du Product Owner du 10 septembre 2026 (« comme WordPress ») ; CDC_CMS_AI_Native_v1.1 §8.1 (authentification du back-office), §8.3 (robustesse du mot de passe), §13.1 (journal d&#39;accès aux données personnelles), §14.11 (le Core démarre sans configuration) ; RGPD art. 37 ; complète l&#39;ADR-0008 et l&#39;ADR-0023</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Depuis l&#39;Epic E6, le premier compte d&#39;une organisation se crée par <code>POST /api/v1/auth/bootstrap</code> : une route ouverte, qui crée un Admin et se referme d&#39;elle-même au premier compte. L&#39;en-tête de <code>app/api/auth.py</code> motive ce choix contre l&#39;alternative évidente — un compte <code>admin/admin</code> posé par une migration, c&#39;est-à-dire un mot de passe par défaut, vulnérabilité en production dans la majorité des installations réelles. Les deux chemins de provisionnement du dépôt s&#39;appuyaient dessus : <code>teuthiscms</code> (ADR-0023) affichait l&#39;identifiant d&#39;organisation à passer à l&#39;amorçage, et <code>docker compose up</code> créait l&#39;organisation de développement pour qu&#39;il soit utilisable.</p><p>Le Product Owner demande qu&#39;une installation neuve <strong>oblige</strong> l&#39;administrateur à choisir son identifiant et son mot de passe et à renseigner l&#39;organisation, « comme WordPress ». L&#39;amorçage ne satisfait pas cette demande, pour deux raisons :</p><ol><li><strong>Il ne fait rien renseigner.</strong> L&#39;organisation garde le nom provisoire que le provisionnement lui a donné (dérivé du nom de projet, ou « Commune de développement »), et sa politique RGPD n&#39;a ni responsable de traitement ni contact de DPO. Le registre des traitements (E5) et la politique de confidentialité générée (E15) ont besoin de ces deux informations, et aucun écran ne les réclame.</li><li><strong>Il a le défaut connu de l&#39;installation WordPress.</strong> Il appartient au premier qui l&#39;appelle. Une organisation provisionnée sur une machine joignable peut être appropriée par n&#39;importe quel visiteur entre le provisionnement et le premier passage de son exploitant.</li></ol><p>Voici ce que fait WordPress. Aucun compte n&#39;existe avant la première visite. Le parcours demande d&#39;abord les identifiants de la base de données (<code>wp-admin/setup-config.php</code>, qui écrit <code>wp-config.php</code>), puis le titre du site, l&#39;identifiant, le mot de passe (un mot de passe fort est proposé) et l&#39;adresse électronique de l&#39;administrateur (<code>wp-admin/install.php</code>). Il n&#39;y a donc pas de mot de passe par défaut. En revanche, le parcours est ouvert à quiconque arrive le premier : c&#39;est le <strong>détournement d&#39;installation</strong>, exploité par des robots qui repèrent les installations neuves et les terminent à la place de leur propriétaire. Quand l&#39;exploitant fait l&#39;installation de bout en bout, l&#39;étape des identifiants de base de données tient lieu de preuve, car un inconnu ne les connaît pas. Mais cette étape disparaît dès que l&#39;hébergeur pré-remplit <code>wp-config.php</code>, comme dans les installations en un clic. Il ne reste alors aucune preuve, et l&#39;écran appartient au premier visiteur.</p><p>Ce CMS est exactement dans ce cas. Ses deux provisionnements « pré-remplissent » tout (base, migrations, organisation), et il ne reste aucune étape que seul l&#39;exploitant saurait franchir.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>On reprend l&#39;installation guidée de WordPress, avec une preuve d&#39;exploitation qui ne peut pas disparaître : une clé d&#39;installation.</strong></p><ol><li><p><strong>Une clé est émise au provisionnement et affichée à l&#39;exploitant seul.</strong> <code>teuthiscms</code> l&#39;affiche une fois, en fin de commande. <code>docker compose up</code> l&#39;imprime dans le journal de <code>cms-api</code> (<code>python -m app.cli.dev_seed</code>), avec une nouvelle clé à chaque démarrage tant que l&#39;organisation n&#39;est pas installée. Elle n&#39;est écrite nulle part en clair : ni dans le README généré, ni dans <code>.env</code>, ni en base, ni dans une réponse d&#39;API. Si elle est perdue, on en émet une nouvelle (<code>python -m manage installation-key</code>, <code>python -m app.cli.installation_key</code>), qui invalide l&#39;ancienne. La clé joue le rôle de l&#39;étape « identifiants de base de données » de WordPress, sans pouvoir être sautée : pour l&#39;obtenir, il faut lire la sortie du provisionnement ou avoir accès à la base.</p></li><li><p><strong>Forme</strong> : 25 caractères de l&#39;alphabet base32 de Crockford (sans <code>I</code>, <code>L</code>, <code>O</code> ni <code>U</code>), en cinq groupes de cinq, soit environ 125 bits, recopiables à la main. La vérification ignore la casse, les tirets et les espaces. <strong>Stockage</strong> : l&#39;empreinte scrypt (<code>hash_password</code>) et la date d&#39;émission sont rangées sous <code>organizations.settings[&quot;installation&quot;]</code>, écrites et effacées sans toucher aux autres namespaces (même patron que <code>write_rgpd_policy</code>). Aucune migration n&#39;est nécessaire.</p></li><li><p><strong><code>POST /api/v1/installation</code></strong> fait en une seule transaction ce que WordPress fait en un écran. La route écrit le nom de l&#39;organisation, puis le responsable de traitement et le contact du DPO dans la politique RGPD, en préservant les autres réglages RGPD déjà décidés. Elle crée ensuite le premier compte <code>admin</code>, efface la clé, journalise <code>PERMISSION_CHANGE</code> et ouvre la session de l&#39;administrateur, qui repart connecté. <code>GET /api/v1/installation/status</code> indique à l&#39;écran d&#39;admin s&#39;il doit s&#39;afficher.</p></li><li><p><strong>L&#39;ordre des contrôles est imposé</strong> :</p><ol><li>organisation inconnue : 404 ;</li><li>organisation déjà installée : 409 ;</li><li>clé absente, fausse ou aucune clé en attente : 403, avec un <code>LOGIN_FAILED</code> journalisé et validé malgré le refus ;</li><li>mot de passe hors politique : 422 ;</li><li>seulement ensuite, les écritures.</li></ol><p>La clé est vérifiée avant le mot de passe, pour que la route ne serve pas à tester la politique de mot de passe sans avoir la clé. L&#39;organisation est relue avec un verrou (<code>SELECT … FOR UPDATE</code>), pour que deux installations simultanées ne puissent pas créer deux administrateurs avec une clé à usage unique.</p></li><li><p><strong>« Installée » garde le même sens</strong> : l&#39;organisation a au moins un compte agent. Un seul prédicat (<code>is_installed</code>) sert l&#39;amorçage, l&#39;installation, le statut et l&#39;émission de clé.</p></li></ol><p><strong>Pas de verrouillage après échecs répétés.</strong> C&#39;est un choix délibéré. À 125 bits, une force brute en ligne n&#39;aboutit pas : il faut de l&#39;ordre de 2^124 essais pour une chance sur deux, et chacun coûte un hachage scrypt au serveur. Un verrou n&#39;ajouterait donc aucune protection, et il deviendrait une arme. L&#39;identifiant d&#39;une organisation n&#39;est pas un secret (il figure dans la configuration de l&#39;admin), et un tiers pourrait épuiser les tentatives pour empêcher l&#39;exploitant d&#39;installer. C&#39;est le raisonnement qui rend temporaire le verrouillage des comptes (<code>RbacPolicy</code>), appliqué ici jusqu&#39;au bout. Chaque échec reste journalisé.</p><p><strong><code>dpo_contact</code> est obligatoire à l&#39;installation</strong>, alors que <code>RgpdPolicy.dpo_contact</code> reste facultatif. Une autorité ou un organisme public est tenu de désigner un délégué à la protection des données (RGPD, art. 37-1-a), et c&#39;est la cible de ce CMS. L&#39;installation est le seul moment où l&#39;on peut exiger cette réponse sans interrompre quelqu&#39;un en plein travail. On peut effacer le contact plus tard : la politique de confidentialité générée (E15) signale alors son absence au lieu de la masquer.</p><p><strong>Le sort de <code>POST /auth/bootstrap</code>.</strong> La route reste, inchangée, la voie des organisations <strong>sans clé</strong> : la suite de tests (près de 190 appels), les intégrations qui provisionnent par l&#39;API, les organisations créées avant cet ADR. Elle <strong>refuse en 409</strong> une organisation dont la clé est en attente, et renvoie vers <code>POST /api/v1/installation</code>. Sans ce refus, la clé ne protégerait rien, puisque le premier visiteur passerait par l&#39;amorçage. La construction du compte (validation du mot de passe, création, journal) est une seule fonction, partagée par les deux routes (<code>_add_first_admin</code>).</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Compte <code>admin/admin</code> posé par une migration</strong></td><td>Écartée depuis l&#39;Epic E6, pour la même raison : un mot de passe par défaut est une vulnérabilité en production dans la majorité des installations réelles. Forcer son changement à la première connexion ne corrige rien : entre le déploiement et cette connexion, le compte appartient à quiconque connaît le couple, c&#39;est-à-dire à tout le monde.</td></tr><tr><td><strong>Mot de passe fixe ou généré, imposé à l&#39;administrateur</strong></td><td>Écartée : la demande est justement que l&#39;exploitant <strong>choisisse</strong> son identifiant et son mot de passe. Un mot de passe généré et affiché au provisionnement revient à une clé d&#39;installation qui ne se remplace pas : il devient le mot de passe du compte, finit recopié dans des notes et n&#39;est jamais changé.</td></tr><tr><td><strong>Installation ouverte, sans preuve (WordPress tel quel)</strong></td><td>Écartée : c&#39;est le détournement d&#39;installation, le défaut qui accompagne le modèle demandé. Ce CMS vise des collectivités, et une organisation appropriée par un tiers avant son exploitant y est un incident de sécurité, pas un simple désagrément.</td></tr><tr><td><strong>Clé écrite dans un fichier du projet (<code>.env</code>, README) ou lue depuis une variable d&#39;environnement</strong></td><td>Écartée : un README ou un <code>.env</code> se versionne, se partage et se recopie dans un ticket, et une clé qui y figure ne prouve plus qu&#39;on est l&#39;exploitant. Une variable d&#39;environnement obligatoire contredirait en outre le principe « le Core démarre sans configuration » (CDC §14.11).</td></tr><tr><td><strong>Installation autorisée seulement depuis <code>localhost</code></strong></td><td>Écartée : l&#39;adresse source ne prouve rien derrière un proxy inverse ou dans un conteneur (toutes les requêtes arrivent de la passerelle Docker), et elle empêcherait d&#39;installer un serveur distant sans tunnel.</td></tr><tr><td><strong>Verrouillage après N clés fausses</strong></td><td>Écartée (voir la Décision) : aucune protection supplémentaire à 125 bits, et un moyen offert de bloquer l&#39;installation légitime.</td></tr><tr><td><strong>Supprimer <code>bootstrap</code></strong></td><td>Écartée : la route sert la suite de tests et les intégrations, qui provisionnent sans clé, et les organisations créées avant cet ADR n&#39;en ont pas. La refuser seulement quand une clé est en attente ferme la faille sans rien casser.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une organisation provisionnée ne peut plus être installée que par quelqu&#39;un qui a lu la sortie du provisionnement ou qui a accès à la base. Le détournement d&#39;installation est fermé sur les deux chemins du dépôt.</li><li>Aucun compte ni mot de passe par défaut n&#39;existe, à aucun moment.</li><li>Le responsable de traitement et le contact du DPO sont renseignés dès le premier jour : le registre des traitements (E5) et la politique de confidentialité générée (E15) ne partent plus d&#39;une organisation anonyme.</li><li>Aucune migration, aucune dépendance ni variable d&#39;environnement n&#39;est ajoutée : la clé vit dans un namespace de <code>organizations.settings</code>.</li><li>La construction du premier administrateur n&#39;existe qu&#39;en un seul endroit : l&#39;amorçage et l&#39;installation ne peuvent pas diverger sur la politique de mot de passe ni sur le journal.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>L&#39;amorçage reste ouvert au premier venu sur une organisation sans clé.</strong> C&#39;est le garde-fou de cet ADR, et il est assumé : une organisation créée par une intégration qui n&#39;émet pas de clé garde le comportement de l&#39;Epic E6. Un nouveau provisionnement doit émettre une clé pour être protégé ; les deux chemins du dépôt le font.</li><li><strong>Avec <code>docker compose up</code>, la clé est dans le journal du conteneur</strong>, lisible par quiconque lit ce journal. Sur un poste de développement, c&#39;est le bon lecteur. Sur une machine partagée, l&#39;exploitant doit protéger l&#39;accès à Docker, qui donne de toute façon accès à la base.</li><li><strong>Une nouvelle clé est émise à chaque redémarrage</strong> de <code>cms-api</code> tant que l&#39;installation n&#39;est pas faite : redémarrer pendant qu&#39;on recopie la clé l&#39;invalide. Le bandeau l&#39;indique, et la commande de régénération évite d&#39;avoir à redémarrer.</li><li><strong>Les organisations déjà installées ne sont pas concernées</strong> : elles ont un compte, donc aucune clé n&#39;est émise et rien n&#39;est demandé. Leur responsable de traitement et leur contact de DPO restent ce qu&#39;ils étaient, éventuellement vides.</li></ul><p><strong>Hors périmètre</strong></p><ul><li><strong>Renommer l&#39;organisation après l&#39;installation.</strong> Aucune route ni permission ne porte aujourd&#39;hui sur l&#39;organisation elle-même. Le nom saisi à l&#39;installation reste définitif tant qu&#39;un chantier dédié n&#39;ouvre pas une telle route.</li><li><strong>Modifier l&#39;identifiant d&#39;un compte existant.</strong> Il reste non modifiable (<code>StaffUserUpdate</code>), pour que le journal d&#39;accès aux données personnelles, qui enregistre des logins, reste lisible.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Back-office Nuxt : écran <code>/installation</code> (<code>apps/admin/pages/installation.vue</code>), livré avec cet ADR — affiché selon <code>GET /api/v1/installation/status</code>, mot de passe fort proposé d&#39;office et robustesse évaluée par <code>POST /api/v1/auth/password-strength</code>.</li><li>[x] Route et permission de gestion de l&#39;organisation après installation (renommage, responsable de traitement, contact du DPO). — Close par le lot 16 (issue #14) : <code>GET</code>/<code>PUT /api/v1/organization</code> sous la permission <code>organization.manage</code>, donnée au seul rôle Administrateur ; le nom reste dans <code>organizations.name</code>, le responsable de traitement et le contact du DPO dans <code>organizations.settings[&#39;rgpd&#39;]</code>, là où l&#39;écran RGPD › Politique les lit et les écrit déjà. Écran <code>/organisation</code> du back-office (<code>apps/admin/pages/organisation.vue</code>) ; recette <code>apps/api/tests/test_gestion_de_l_organisation.py</code>.</li><li>[x] Intégrations qui provisionnent des organisations par d&#39;autres voies : émettre une clé (<code>issue_installation_key</code>) au lieu de compter sur l&#39;amorçage. — Close par l&#39;ADR-0045 : l&#39;image de production provisionne par <code>python -m app.cli.provision</code>, qui crée l&#39;organisation sans compte ni clé imprimée (ses journaux peuvent partir vers un agrégateur, ADR-0039), et la clé s&#39;émet explicitement par <code>python -m app.cli.installation_key</code>, qui suit <code>TEUTHIS_ORGANIZATION_ID</code> ; recette <code>apps/api/tests/test_provision.py</code>.</li></ul>',25)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
